def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    from collections import namedtuple

    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f'Name must be a valid identifier: {name!r}')

    if not isinstance(fields, (list, tuple)):
        raise TypeError(f'Fields must be a list or tuple: {fields!r}')

    for field in fields:
        if not isinstance(field, str) or not field.isidentifier():
            raise TypeError(f'Field names must be valid identifiers: {field!r}')

    if not isinstance(srid_map, dict):
        raise TypeError(f'SRID map must be a dictionary: {srid_map!r}')

    class _Point(namedtuple(name, fields)):
        __slots__ = ()
        _srid_map = srid_map

        def __new__(cls, *args, **kwargs):
            instance = super(_Point, cls).__new__(cls, *args, **kwargs)
            if not hasattr(instance, 'srid'):
                instance.srid = None
            return instance

        @property
        def srid(self):
            return self._srid

        @srid.setter
        def srid(self, value):
            if value is not None and value not in self._srid_map:
                raise ValueError(f'Invalid SRID: {value}. Valid SRIDs are: {list(self._srid_map.keys())}')
            self._srid = value

    return _Point

