def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    from concurrent.futures import ThreadPoolExecutor
    from itertools import islice

    def partition(lst, n):
        """Yield successive n-sized chunks from lst."""
        for i in range(0, len(lst), n):
            yield lst[i:i + n]

    def run_cmd_partition(run_cmd):
        try:
            if color and os.name != 'nt':
                result = subprocess.run(['script', '-qc', ' '.join(run_cmd)], check=False, capture_output=True)
            else:
                result = subprocess.run(run_cmd, check=False, capture_output=True)
            return result.returncode, result.stdout, result.stderr
        except Exception as e:
            return 1, b'', str(e).encode()

    def _get_platform_max_length():
        import sys
        return min(8192, sys.maxsize)

    _max_length = _max_length or _get_platform_max_length()
    retcode = 0
    stdout = b''

    try:
        cmd = list(cmd)
    except TypeError:
        return 1, b'cmd must be a sequence of strings'

    partitions = list(partition(varargs, _max_length // (len(cmd) + 1)))

    threads = min(len(partitions), target_concurrency)
    with ThreadPoolExecutor(max_workers=threads) as executor:
        results = executor.map(run_cmd_partition, (cmd + list(part) for part in partitions))

        for proc_retcode, proc_out, proc_err in results:
            retcode |= proc_retcode
            stdout += proc_out
            if proc_err:
                print(proc_err.decode(), file=sys.stderr)

    return retcode, stdout

