def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Use a set to track seen classes and a list to maintain order
        seen = set()
        min_bases = []
        for cls in classes:
            if cls not in seen:
                seen.add(cls)
                min_bases.append(cls)
                # Remove subclasses from the list
                min_bases = [c for c in min_bases if not issubclass(cls, c)]
        return min_bases
    except TypeError as e:
        raise TypeError("All elements in classes must be class types") from e

