def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not isinstance(app, krake.data.kubernetes.Application):
        raise ValueError("The provided object is not an instance of krake.data.kubernetes.Application")

    default_schema = {}
    try:
        for resource in app.spec.manifest:
            resource_name = resource.get('kind')
            if resource_name and resource_name not in app.spec.observer_schema:
                # Define a default observer schema for the resource
                default_schema[resource_name] = {
                    "metrics": {
                        "cpu_usage": {"json_path": ".status.usage.cpu"},
                        "memory_usage": {"json_path": ".status.usage.memory"}
                    }
                }
    except AttributeError:
        raise ValueError("The application object does not have the expected structure")

    # Update the application's observer schema with the defaults
    app.spec.observer_schema.update(default_schema)

