def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        The source directory or zipfile name
    xmls : list
        List of XML filenames
    files : list
        List of files in the folder or zipfile

    Returns
    -------
    dict
        Key: Name of the XML files
        Value: List of files associated with the XML file
    """
    from pathlib import Path
    import zipfile
    import os

    file_dict = {xml: [] for xml in xmls}

    def get_basename(file_path):
        return os.path.splitext(os.path.basename(file_path))[0]

    if source.endswith('.zip'):
        try:
            with zipfile.ZipFile(source, 'r') as z:
                z_files = z.namelist()
                for f in z_files:
                    base_name = get_basename(f)
                    for xml in xmls:
                        if base_name == get_basename(xml):
                            file_dict[xml].append(f)
        except zipfile.BadZipFile:
            raise ValueError(f"The provided source {source} is not a valid zip file.")
        except Exception as e:
            raise Exception(f"An error occurred while processing the zip file: {e}")
    else:
        try:
            for f in files:
                base_name = get_basename(f)
                for xml in xmls:
                    if base_name == get_basename(xml):
                        file_dict[xml].append(os.path.join(source, f))
        except Exception as e:
            raise Exception(f"An error occurred while processing the directory: {e}")

    return file_dict

