def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections import namedtuple
    from itertools import product

    Expression = namedtuple('Expression', ['op', 'left', 'right'])

    def simplify(expr):
        if isinstance(expr, Expression):
            if expr.op == '&':
                if expr.left == expr.right:
                    return expr.left
                if isinstance(expr.right, Expression) and expr.right.op == '|':
                    if expr.left == expr.right.left:
                        return expr.left
                    if expr.left == expr.right.right:
                        return expr.left
                if isinstance(expr.left, Expression) and expr.left.op == '|':
                    if expr.left.left == expr.right:
                        return expr.right
                    if expr.left.right == expr.right:
                        return expr.right
            elif expr.op == '|':
                if expr.left == expr.right:
                    return expr.left
                if isinstance(expr.right, Expression) and expr.right.op == '&':
                    if expr.left == expr.right.left:
                        return expr.left
                    if expr.left == expr.right.right:
                        return expr.left
                if isinstance(expr.left, Expression) and expr.left.op == '&':
                    if expr.left.left == expr.right:
                        return expr.right
                    if expr.left.right == expr.right:
                        return expr.right
        return expr

    def apply_absorption(expr):
        if isinstance(expr, Expression):
            expr = Expression(expr.op, apply_absorption(expr.left), apply_absorption(expr.right))
            return simplify(expr)
        return expr

    return [apply_absorption(arg) for arg in args]

