def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    if not version_dirs:
        raise ValueError("version_dirs cannot be empty.")

    root_inventory = {}
    try:
        with open(os.path.join(self.root_dir, 'inventory.json'), 'r') as f:
            root_inventory = json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError("Root inventory file not found.")
    except json.JSONDecodeError as e:
        raise ValueError(f"Error decoding root inventory JSON: {e}")

    differing_digests = {}

    for version in version_dirs:
        version_dir = os.path.join(self.base_path, version)
        version_inventory_path = os.path.join(version_dir, 'inventory.json')

        if not os.path.exists(version_dir):
            raise FileNotFoundError(f"Version directory {version_dir} does not exist.")

        try:
            with open(version_inventory_path, 'r') as f:
                version_inventory = json.load(f)
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file for version {version} not found.")
        except json.JSONDecodeError as e:
            raise ValueError(f"Error decoding inventory JSON for version {version}: {e}")

        for item, digest in version_inventory.items():
            if item in root_inventory and root_inventory[item] != digest:
                differing_digests[item] = digest

    return differing_digests

