def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = {cls}

    while queue:
        c = queue.pop()
        sc = c.__subclasses__()
        for subclass in sc:
            if subclass not in seen:
                seen.add(subclass)
                queue.add(subclass)

    seen.remove(cls)
    return seen

