def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import json
    import toml
    import yaml
    from logging import LogRecord

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        if not os.path.exists(config_filename):
            log_records.append(LogRecord(name='config_loader', level=logging.ERROR, pathname=config_filename, lineno=0,
                                         msg=f"Configuration file does not exist: {config_filename}", args=(), exc_info=None))
            continue

        try:
            with open(config_filename, 'r') as file:
                if config_filename.endswith('.json'):
                    config = json.load(file)
                elif config_filename.endswith('.toml'):
                    config = toml.load(file)
                elif config_filename.endswith(('.yaml', '.yml')):
                    config = yaml.safe_load(file)
                else:
                    log_records.append(LogRecord(name='config_loader', level=logging.ERROR, pathname=config_filename, lineno=0,
                                                 msg=f"Unsupported configuration file format: {config_filename}", args=(), exc_info=None))
                    continue

                if resolve_env:
                    config = resolve_environment_variables(config)

                if overrides:
                    config.update(overrides)

                config_dict[config_filename] = config

        except (json.JSONDecodeError, toml.TomlDecodeError, yaml.YAMLError) as e:
            log_records.append(LogRecord(name='config_loader', level=logging.ERROR, pathname=config_filename, lineno=0,
                                         msg=f"Failed to parse configuration file: {config_filename}", args=(), exc_info=e))

    return config_dict, log_records

def resolve_environment_variables(config):
    import os
    if isinstance(config, dict):
        return {k: resolve_environment_variables(v) for k, v in config.items()}
    elif isinstance(config, list):
        return [resolve_environment_variables(item) for item in config]
    elif isinstance(config, str):
        return os.path.expandvars(config)
    return config

