def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclass = None
    for base in bases:
        try:
            # Infer the metaclass from each base class
            base_metaclass = type(base)
            if metaclass is None:
                metaclass = base_metaclass
            elif metaclass is not base_metaclass:
                # If there is a conflict in metaclasses, raise an error
                raise TypeError("Metaclass conflict: the metaclass of a derived class must be a subtype of the metaclasses of all its bases")
        except Exception as e:
            # Handle any exceptions that occur during metaclass inference
            raise TypeError(f"Error determining metaclass: {e}")

    return metaclass if metaclass is not type else None

