def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re

    tags = set()
    code_block = False
    code_block_starters = {r'```', r'```python', r'```code'}
    code_block_enders = {r'```'}
    lines = text.split('\n')
    new_lines = []

    for line in lines:
        # Check for code block starts and ends
        if any(line.strip().startswith(starter) for starter in code_block_starters):
            code_block = True
        if any(line.strip().endswith(ender) for ender in code_block_enders):
            code_block = False

        if not code_block:
            # Find tags in the line
            tag_pattern = r'(\B#\w*[a-zA-Z]+\w*)'
            for match in re.finditer(tag_pattern, line):
                tag = match.group(0)
                tags.add(tag)
                if replacer is not None:
                    try:
                        replacement = replacer(tag)
                        line = line[:match.start()] + replacement + line[match.end():]
                    except Exception as e:
                        print(f"Error replacing tag {tag}: {e}")

        new_lines.append(line)

    new_text = '\n'.join(new_lines)
    return tags, new_text

