def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try parsing JSON format
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing XRD format
        try:
            root = ET.fromstring(document)
            if root.tag != "{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD":
                raise ValueError("Invalid XRD document")
            links = root.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
            parsed_data = {}
            for link in links:
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    parsed_data[rel] = href
            return parsed_data
        except (ET.ParseError, ValueError):
            logger.warning("parse_diaspora_webfinger: Unable to parse document")
            return {}

