def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    import yaml
    from jsonschema import validate, ValidationError

    if spec_content is None:
        raise IRValidatorException("spec_content argument must be supplied")

    try:
        spec_data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"There was a problem parsing the spec content.\n{e}")

    required_fields = {'field1', 'field2', 'field3'}  # Example required fields
    missing_fields = required_fields - spec_data.keys()

    if missing_fields:
        raise IRValidatorException(f"Missing required fields in spec content: {missing_fields}")

    schema = {
        "type": "object",
        "properties": {
            "field1": {"type": "string"},
            "field2": {"type": "integer"},
            "field3": {"type": "boolean"}
        },
        "required": list(required_fields)
    }

    try:
        validate(instance=spec_data, schema=schema)
    except ValidationError as ve:
        raise IRValidatorException(f"Validation error in spec content: {ve.message}")

    return spec_data

