def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    import yaml
    from pathlib import Path

    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    yaml_file_path = Path(yaml_file)
    if not yaml_file_path.exists():
        raise FileNotFoundError(f"The file {yaml_file} does not exist")

    try:
        with yaml_file_path.open('r') as file:
            data = yaml.safe_load(file)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")

    # Define the required fields for validation
    required_fields = {'name', 'version', 'description'}
    missing_fields = required_fields - set(data.keys())
    if missing_fields:
        raise IRValidatorException(f"Missing required fields in YAML file: {missing_fields}")

    return data

