def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    try:
        if not isinstance(args, dict):
            raise ValueError("Arguments must be provided as a dictionary with 'value', 'min', and 'max' keys.")

        value = args.get('value')
        min_value = args.get('min')
        max_value = args.get('max')

        if value is None or min_value is None or max_value is None:
            raise ValueError("Arguments must include 'value', 'min', and 'max'.")

        if not isinstance(value, (int, float)) or not isinstance(min_value, (int, float)) or not isinstance(max_value, (int, float)):
            raise TypeError("Values for 'value', 'min', and 'max' must be numbers.")

        if min_value > max_value:
            raise ValueError("Minimum value must be less than or equal to maximum value.")

        if not (min_value <= value <= max_value):
            raise ValueError(f"Value {value} is not between {min_value} and {max_value}.")

    except Exception as e:
        raise TypeError(f"Invalid arguments: {e}")

