def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    try:
        parser = self.parsers[parser_name]
    except KeyError:
        raise ValueError(f"No parser found for command: {parser_name}")

    for arg, value in values_dict.items():
        try:
            action = next((action for action in parser._actions if action.dest == arg), None)
            if action:
                # Use the same logic as argparse to convert the value
                values_dict[arg] = action.type(value) if action.type else value
        except Exception as e:
            raise ValueError(f"Error converting argument '{arg}' with value '{value}': {str(e)}")

